<student_code untrusted="true">
=== submission_07.ino ===
   1| /*
   2|  * Lab 4 - button toggle
   3|  *
   4|  * Toggle on the falling edge of D2 (button press). Bounce is handled by
   5|  * ignoring any further edges for HOLDOFF_MS after an accepted press.
   6|  * This responds instantly on the first edge, so there is no added latency.
   7|  *
   8|  * Pins: D2 button (INPUT_PULLUP), D13 LED. Serial1 at 9600 baud.
   9|  */
  10| 
  11| const int buttonPin = 2;
  12| const int ledPin    = 13;
  13| const unsigned long HOLDOFF_MS = 30;
  14| 
  15| int  prev = HIGH;             // reading from the previous loop
  16| bool ledOn = false;
  17| unsigned long acceptedAt = 0; // time of the last accepted press
  18| 
  19| void setup() {
  20|   pinMode(buttonPin, INPUT_PULLUP);
  21|   pinMode(ledPin, OUTPUT);
  22|   digitalWrite(ledPin, LOW);
  23|   Serial1.begin(9600);
  24| }
  25| 
  26| void loop() {
  27|   int cur = digitalRead(buttonPin);
  28| 
  29|   // HIGH -> LOW transition = button pressed
  30|   if (prev == HIGH && cur == LOW) {
  31|     if (millis() - acceptedAt > HOLDOFF_MS) {
  32|       ledOn = !ledOn;
  33|       digitalWrite(ledPin, ledOn ? HIGH : LOW);
  34|       Serial1.println(ledOn ? "ON" : "OFF");
  35|       acceptedAt = millis();
  36|     }
  37|   }
  38| 
  39|   prev = cur;
  40| }
</student_code>
